        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Qeyri-neft ÜDM-nin qısamüddətli proqnozlaşdırılması modellərin qurulması$wp$, ARRAY[$wp$Nəzrin Ramazanova$wp$, $wp$Oqtay Qəhrəmanov$wp$]::text[], $wp$Qeyri-neft ÜDM-in qısamüddətli proqnozlaşdırılması onun ortamüddətli proqnozunun hazırlanması üçün zəruridir. Bu məqalədə qeyri-neft ÜDM-in rüblük artımını proqnozlaşdırmaq üçün üç əsas proqnozlaşdırma modelinin (Vektor Avtoreqressiya (VAR), Qarışıq Məlumat Nümunələşdirmə (MIDAS) və Dinamik Faktor Modellərinin (DFM)) keyfiyyəti qiymətləndirilir. Empirik nəticələr göstərir ki, əksər modellər rüblük proqnoz nəticələri üzrə AR(1) modelini üstələyir. Məqalədə hər bir modelinin üstünlüklərindən istifadə etmək məqsədilə proqnozların kombinasiya edilmiş nəticələrinə də baxılır. Orta kvadratik xəta (MSE) çəkilərinə əsaslanan proqnozların kombinasiyası fərdi modellərlə müqayisədə proqnozun dəqiqliyini artırır. Ümumilikdə, nəticələr Azərbaycanın dinamik iqtisadi mühitində qısamüddətli ÜDM artımı proqnozlarının dəqiqliyini artırmaq üçün çoxşaxəli proqnozlaşdırma strategiyasının üstünlüklərini vurğulayır. Nəticələr kombinasiya üsullarının istifadəsinin qısamüddətli proqnozların etibarlılığını gücləndirməkdə praktik faydalarını önə çəkir.$wp$, ARRAY[$wp$qısamüddətli proqnozlaşdırma$wp$, $wp$qeyri-neft ÜDM$wp$, $wp$proqnozların kombinasiyası$wp$]::text[], $wp$70704377f027dee765af34861.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Development of Short-term Forecasting Models for Non-oil GDP$wp$, ARRAY[$wp$Nazrin Ramazanova$wp$, $wp$Ogtay Gahramanov$wp$]::text[], $wp$Short-term forecasting of non-oil GDP is essential for preparing its medium-term projections. This paper evaluates the performance of three key forecasting models—Vector Autoregression (VAR), Mixed Data Sampling (MIDAS), and Dynamic Factor Models (DFM)—in predicting quarterly growth of non-oil GDP. The empirical results show that most models outperform the AR(1) benchmark in quarterly forecasts. To leverage the strengths of each model, the study also examines combined forecast results. A forecast combination based on mean squared error (MSE) weights improves forecast accuracy compared to individual models. Overall, the findings highlight the advantages of a multi-model forecasting strategy for enhancing the accuracy of short-term GDP growth predictions in Azerbaijan’s dynamic economic environment. The results emphasize the practical benefits of using combination methods to strengthen the reliability of short-term forecasts.$wp$, ARRAY[$wp$short-term forecasting$wp$, $wp$non-oil GDP$wp$, $wp$forecast combination$wp$]::text[], $wp$14b8ec3b4f02cb74518c0ac0b.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 03-2024, page-888
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 3 AND year = 2024) OR legacy_page_id = 888)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (3, 2024, 'az', ARRAY[$wp$E31$wp$, $wp$E37$wp$, $wp$Q11$wp$]::text[], 888, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İdxal çəkiləri nəzərə alınmaqla hesablanmış qlobal ərzaq qiymətlərinin proqnozlaşdırılması$wp$, ARRAY[$wp$Fəridə Vəliyeva$wp$]::text[], $wp$Məqalə ərzaq məhsullarının Azərbaycanın idxal səbətindəki çəkiləri nəzərə alınmaqla modifikasiya olunmuş qlobal ərzaq qiymətləri indeksinin proqnozlaşdırılmasına həsr edilmişdir. Qiymətləndirmə 2002-2024-cü illər üzrə rüblük zaman sırası məlumatlarından istifadə etməklə avtoreqressiv paylanmış gecikmə (ARDL) modelinin tətbiqi ilə aparılmışdır. Nəticələr göstərir ki, modifikasiya olunmuş qlobal ərzaq qiymətləri indeksi yerli ərzaq inflyasiyasını daha yaxşı izah edir. Qeyd edək ki, iki indeks arasında korrelyasiya əmsalı digər beynəlxalq qurumlar tərəfindən açıqlanan indeksə (BVF, FAO, DB) nəzərən daha yüksəkdir (0.48). Beləliklə, bu indeksin proqnozlaşdırılması qlobal ərzaq bazarında baş verən tendensiyaların Azərbaycana ola biləcək mümkün təsirlərini daha dəqiq qiymətləndirməyə imkan yaradır.$wp$, ARRAY[$wp$qlobal ərzaq qiymətləri$wp$, $wp$ərzaq inflyasiyası$wp$, $wp$inflyasiya$wp$, $wp$ARDL$wp$]::text[], $wp$6b2a59076e45a6a868b941044.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Forecasting of Global Food Prices Adjusted for Import Weights$wp$, ARRAY[$wp$Farida Valiyeva$wp$]::text[], $wp$This study focuses on forecasting a modified global food price index that incorporates the weights of food products in Azerbaijan’s import basket. The estimation was carried out by applying the autoregressive distributed lag (ARDL) model using quarterly time series data for 2002-2024. Empirical results indicate that the modified global food price index better captures domestic food inflation dynamics. It should be noted that, the correlation coefficient between this index and domestic food inflation is higher (0.48) compared to indices published by other international institutions such as the IMF, FAO, and the World Bank. These findings suggest that forecasting the modified index offers a more precise framework for evaluating the possible impacts of global food market developments on Azerbaijan.$wp$, ARRAY[$wp$global food prices$wp$, $wp$food inflation$wp$, $wp$inflation$wp$, $wp$ARDL$wp$]::text[], $wp$748fb606db5ac3949f27fdf41.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 02-2024, page-887
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 2 AND year = 2024) OR legacy_page_id = 887)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (2, 2024, 'en', ARRAY[$wp$E30$wp$, $wp$E31$wp$, $wp$E52$wp$, $wp$E58$wp$]::text[], 887, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Supermarket məlumatları əsasında Azərbaycanda inflyasiyanın tələb və təklif komponentlərinin müəyyənləşdirilməsi$wp$, ARRAY[$wp$Xəzan Baxşalıyev$wp$, $wp$Vüqar Əhmədov$wp$]::text[], $wp$Təklif və tələb arasındakı tarazlıq inflyasiyaya təsir göstərir və bu iki amildən hansının üstünlük təşkil etməsi iqtisadi siyasət üçün mühüm əhəmiyyət kəsb edir. Təklif və tələb amillərinin inflyasiyaya töhfələrini ayırd etmək iqtisadi şoklar zamanı inflyasiyanın nədən qaynaqlandığı haqqında məlumat verir və bu isə pul siyasətinin formalaşdırılması üçün vacib əhəmiyyət daşıyır. Dekompozisiya yanaşması nəzəri çərçivələri sınaqdan keçirmək üçün bir alət kimi çıxış edir və siyasətçilərə, mütəxəssislərə inflyasiyaya töhfə verən amilləri izləməyə imkan yaradır. Məqalə inflyasiyanı təklif və tələb üzrə komponentlərə ayırmaq məqsədi daşıyır və bu məqsədlə alternativ mikro-əsaslı yanaşmadan istifadə edilir. Məqalə qiymət formalaşmasının fundamental nəzəriyyəsinə, yəni qiymət və miqdar arasındakı əlaqəyə əsaslanır. Qiymətləndirmələrdə 2020–2025-ci illər ərzində Azərbaycanın iri supermarket şəbəkələrində satılan 2559 məhsul üzrə aylıq mikro-məlumatlardan istifadə edilmişdir. Hər bir məhsul üçün ayrıca Struktur Vektor Avtoreqressiv (SVAR) modeli qurularaq təhlil aparılmış və ümumilikdə 2559 SVAR modeli vasitəsilə inflyasiyanın tələb və ya təklif şoklarından qaynaqlandığı müəyyən edilmişdir.
SVAR modellərinin ilkin nəticələri tələb şoklarının xüsusilə COVID-19 pandemiyasından sonrakı bərpa dövründə inflyasiyanın əsas drayveri olduğunu göstərmişdir. Bu isə mövcud makro iqtisadi modellərdə kifayət qədər əks olunmamışdır. Tədqiqat işi tələbə bağlı inflyasiyanın əhəmiyyətini qiymətləndirmək üçün bir alət təqdim edərək, siyasətçilərə real prosesləri anlamağa və düzgün siyasət qərarlarına kömək edir.$wp$, ARRAY[$wp$Təklif və tələb əsaslı inflyasiya$wp$, $wp$SVAR modeli$wp$, $wp$supermarket məlumatları$wp$]::text[], $wp$5f061a3e9819745e3c6a047b8.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Decomposition of inflation in Azerbaijan into supply and demand components based on supermarket data$wp$, ARRAY[$wp$Khazan Bakhshaliyev$wp$, $wp$Vugar Ahmadov$wp$]::text[], $wp$The balance between supply and demand influences inflation and understanding whether one factor predominates the other has significant implications for economic policy. Distinguishing the contributions of supply and demand factors to inflation offers insight into the primary drivers of inflation during economic shocks and is especially important for monetary policymaking. Decomposition serves as a tool for testing theoretical frameworks and enables policymakers and practitioners to monitor the factors contributing to inflation in real-time. In this context, the paper aims to decompose inflation into supply- and demand-driven components using an alternative micro-founded approach. It relies on a fundamental theory of price formation: the relationship between price and quantity, based on monthly data for 2,559 goods sold in one of the largest supermarket chains in Azerbaijan from 2020 and 2025. For each item, a structural vector autoregression (SVAR) model is estimated individually, resulting in 2,559 SVAR models used to identify whether observed inflation is driven by demand or supply shocks.
Preliminary findings from SVAR models highlight that demand is one of the main contributors to inflation, particularly in the post-COVID recovery period, which macro-founded models had previously underestimated. Consequently, this study contributes to the Central Bank of Azerbaijan by providing a tool to estimate the importance of demand-pull inflation, helping policymakers stay ahead of the curve.$wp$, ARRAY[$wp$supply and demand driven inflation$wp$, $wp$SVAR model$wp$, $wp$supermarket data$wp$]::text[], $wp$15b3461fac07e0a746714595a.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 01-2024, page-882
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 1 AND year = 2024) OR legacy_page_id = 882)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (1, 2024, 'en', ARRAY[$wp$E32$wp$, $wp$E37$wp$, $wp$E47$wp$, $wp$E52$wp$]::text[], 882, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Azərbaycanın Rüblük Proqnozlaşdırma Modeli (AzİM 1.0)$wp$, ARRAY[$wp$Tural Yusifzadə$wp$, $wp$Nəzrin Ramazanova$wp$, $wp$Ramiz Rəhmanov$wp$, $wp$Vüqar Əhmədov$wp$]::text[], $wp$Bu məqalədə ədəbiyyatlarda açıq iqtisadiyyat kəsir modeli adlanan və Azərbaycan iqtisadiyyatı timsalında qurulan rüblük proqnozlaşdırma modelinin (AzİM 1.0) ilkin versiyası təqdim olunur. Model proqnozlaşdırma, simulyasiya və pul siyasətinin təhlili məqsədləri üçün nəzərdə tutulmuşdur. Bu model beş əsas blokdan ibarətdir: (i) qeyri-neft buraxılış kəsirini əhatə edən ümumi tələb bloku; (ii) inflyasiya və inflyasiya gözləntilərini modelləşdirən Fillips əyrisi (inflyasiyanın proqnozlaşdırılması) bloku; (iii) nominal lövbər rolunu oynayan riskə uyğunlaşdırılmış açıq faiz dərəcəsi pariteti bloku; (iv) pul siyasətinə reaksiya funksiyasını müəyyən edən Teylor qaydası (qısamüddətli faiz dərəcəsi) bloku; (v) xarici sektor bloku. AzİM 1.0 qismən-struktur yeni keynes nəzəri çərçivəsinə əsaslanan modeldir və Azərbaycan iqtisadiyyatının xüsusiyyətlərini, xüsusilə də transmissiya mexanizmi və pul siyasətinin formalaşma prosesini nəzərə almaqla qurulmuşdur. Modelin kalibrasiyası Azərbaycan üzrə aparılmış empirik qiymətləndirmələrə, beynəlxalq ədəbiyyata, oxşar ölkə təcrübələrinə və tarixi məlumatlara əsaslanır. Modelin dayanıqlığını və tətbiqə yararlılığını qiymətləndirmək məqsədilə impuls-cavab analizləri, tənliklərin dekompozisiyası və nümunədaxili simulyasiyalar həyata keçirilmişdir.$wp$, ARRAY[$wp$rüblük proqnoz modeli$wp$, $wp$Azərbaycan iqtisadiyyatı$wp$, $wp$proqnozlaşdırma və siyasət təhlili$wp$, $wp$pul siyasəti$wp$]::text[], $wp$4a15963000e5bdaae298d910d.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Quarterly Projection Model of Azerbaijan (AzIM 1.0)$wp$, ARRAY[$wp$Tural Yusifzada$wp$, $wp$Nazrin Ramazanova$wp$, $wp$Ramiz Rahmanov$wp$, $wp$Vugar Ahmadov$wp$]::text[], $wp$This paper presents the first version of the Azerbaijan Quarterly Projection Model (AzIM 1.0), a forward-looking, open-economy gap model. The model is designed for forecasting, simulations, and monetary policy analysis. It consists of five main building blocks: (i) aggregate demand block consisting of the non-oil output gap, (ii) a Phillips curve (inflation forecasting) block modeling inflation and inflation expectations, (iii) a risk adjusted uncovered interest rate parity block serving as the nominal anchor; (iv) Taylor rule (short-term interest rate) block that defines the monetary policy reaction function; and (v) an external sector block. AzIM 1.0 is based on a semi-structural New Keynesian framework, which has been adapted to reflect the specific characteristics of the Azerbaijani economy, particularly the transmission mechanisms and formulation of the monetary policy. The model calibration is informed by econometric estimations for Azerbaijan, insights from international literature and comparable country experiences, as well as historical trends. To assess the model’s robustness and adequacy, we conduct impulse response analysis, equation decomposition, and in-sample simulations.$wp$, ARRAY[$wp$Quarterly Projection Model$wp$, $wp$the Azerbaijani economy$wp$, $wp$forecasting and policy analysis$wp$, $wp$monetary policy$wp$]::text[], $wp$fd87239a9830eee34853c62d8.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
