        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Maliyyə inklüzivliyi və iqtisadi artım arasında əlaqə: Azərbaycan nümunəsi$wp$, ARRAY[$wp$Zübeydə İmanova$wp$]::text[], $wp$Dünya Bankı maliyyə inklüzivliyini (Mİ) dayanıqlı inkişafı stimullaşdıran amillərdən biri kimi müəyyənləşdirmişdir. Mİ-nin təmin olunması inkişaf etməkdə olan ölkələrdə iqtisadi artımın təşviq aləti kimi qəbul edilmişdir. Əvvəlki tədqiqat işlərindən fərqli olaraq bu tədqiqatda maliyyə inklüzivliyi və iqtisadi artım arasındakı əlaqə Azərbaycanda COVID-19 pandemiyasının təsiri nəzərə alınmaqla ekonometrik qiymətləndirmə aparılaraq araşdırılmışdır. Bu məqsədlə bir neçə dəyişənin əsasında PCA metodu ilə qiymətləndirilən çoxölçülü maliyyə inklüzivliyi indeksindən istifadə edilmişdir. Maliyyə inklüzivliyi və iqtisadi artım arasında qısamüddətli və uzunmüddətli əlaqələr ARDL-bound test və ECM yanaşması istifadə olunaraq qiymətləndirilmişdir. Nəticələrə görə Azərbaycanda uzunmüddətli dövrdə iqtisadi artım və maliyyə inklüzivliyi arasında kointeqrasiya əlaqəsi mövcuddur və maliyyə inklüzivliyi adambaşına düşən real qeyri-neft ÜDM-ə artırıcı təsir göstərir. Əldə olunan nəticələr iqtisadi aktivliyin yüksəldilməsi və onun dayanıqlığının dəstəklənməsi baxımından maliyyə inklüzivliyinin mühümlüyünü əks etdirir.$wp$, ARRAY[$wp$maliyyə inklüzivliyi$wp$, $wp$iqtisadi artım$wp$, $wp$əsas komponentin təhlili (PCA)$wp$, $wp$avtoreqressiv paylanmış gecikmə (ARDL)$wp$, $wp$Xətaların təshihi modeli (ECM)$wp$]::text[], $wp$2e401ab54327d7d62b517f2ce.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$The relationship between financial inclusion and economic growth: the case of Azerbaijan$wp$, ARRAY[$wp$Zubeyda Imanova$wp$]::text[], $wp$The World Bank has identified financial inclusion (FI) as a key driver of sustainable development. In developing countries with limited access to financial services, FI can serve as a powerful incentive for economic growth. This study investigates the relationship between FI and economic growth in Azerbaijan from 2010 to 2022, considering the effects of the COVID-19 pandemic. A multi-dimensional financial inclusion index was constructed using the Principal Component Analysis (PCA) method to combine several variables. The short-run and long-run relationships between FI and economic growth were analyzed using the Autoregressive Distributed Lag (ARDL) bound test and the Error Correction Model (ECM) approach. The results indicate a long-term cointegration relationship between economic growth and FI in Azerbaijan, with FI positively affecting real non-oil GDP per capita. These findings highlight the critical role of FI in enhancing economic activity and promoting sustainable economic growth.$wp$, ARRAY[$wp$financial inclusion$wp$, $wp$economic growth$wp$, $wp$principal component analysis (PCA)$wp$, $wp$autoregressive distributed lag (ARDL)$wp$, $wp$error detection model (ECM)$wp$]::text[], $wp$0737f4659999b18f63de2c016.pdf$wp$);
        created := created + 1;
