        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Neytral faiz dərəcəsinin qiymətləndirilməsi: Azərbaycan nümunəsi$wp$, ARRAY[$wp$Nəzrin Ramazanova$wp$]::text[], $wp$Neytral faiz dərəcəsi mərkəzi banklar tərəfindən pul siyasətinin formalaşdırılmasında geniş istifadə edilir. Tədqiqat işində neytral real faiz dərəcəsi inflyasiyanın hədəf səviyyəsinə və ÜDM-in təbii səviyyəsinə uyğun gələn faiz dərəcəsi kimi qəbul edilmişdir. Azərbaycan üzrə neytral faiz dərəcəsinin qiymətləndirilməsi üçün Laubach və Uilyams (2003) metodologiyası tətbiq edilmişdir. Kalman filtri vasitəsilə neytral faiz dərəcəsi, potensial məhsul və onun trend artım tempi birgə qiymətləndirilmiş və empirik əlaqə araşdırılmışdır. Nəticələr göstərir ki, Azərbaycanda neytral real faiz dərəcəsi orta hesabla təxminən 3.1 faiz qiymətləndirilmişdir. Empirik nəticələr qiymətləndirmə dövrünün əvvəli ilə müqayisədə neytral faiz dərəcəsində bir qədər azalma olduğunu göstərir. Neytral real faiz dərəcəsinin dekompozisiyasına əsasən azalmanın əsas səbəbi qiymətləndirmə dövrünün sonunda ÜDM-in potensial artımının yavaşlamasıdır.$wp$, ARRAY[$wp$neytral faiz dərəcəsi$wp$, $wp$potensial məhsul$wp$, $wp$məhsul buraxılışı$wp$, $wp$pul siyasəti$wp$]::text[], $wp$8e1a7efb0afdf70dcde6c182a.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Estimating Natural Rate of Interest. The Case for Azerbaijan$wp$, ARRAY[$wp$N.Ramazanova$wp$]::text[], $wp$The natural rate of interest is widely used by central banks as a policy benchmark to determine the stance of the monetary policy. This study defines the natural rate of interest as the real short-term interest rate consistent with output at its potential and stable inflation. To estimate the natural rate of interest in Azerbaijan, the methodology by Laubach and Williams (2003) has been implemented. Kalman filter is applied to jointly estimate the natural rate of interest, potential output, and its trend growth rate, and examine the empirical relationship between estimated unobserved series for the period 2004:1 to 2023:2. The findings indicate that the natural rate of interest in Azerbaijan has averaged approximately 3.1 percent. The empirical results also reveal a slight decrease in the natural rate of interest over the sample period, mostly due to the slowdown in potential GDP growth.$wp$, ARRAY[$wp$natural rate of interest$wp$, $wp$potential output$wp$, $wp$output gap$wp$, $wp$monetary policy$wp$]::text[], $wp$50943ad1cee2446c38c317057.pdf$wp$);
        created := created + 1;
