        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Ödəniş məlumatları əsasında ÜDM-in naukastinqi modelinin qurulması$wp$, ARRAY[$wp$İlkin Hüseynov$wp$, $wp$Nəzrin Ramazanova$wp$, $wp$Hikmət Vəlirzayev$wp$]::text[], $wp$Tədqiqat işində ödəniş sistemləri məlumatları əsasında Azərbaycanda iqtisadi aktivliyin ölçülməsi (naukastinqi) araşdırılmışdır. Günlük ödəniş əməliyyatları əsasında nominal ümumi daxili məhsulun (ÜDM) rüblük və illik artım templərinin naukastinqi üçün Dinamik faktor modeli (DFM) və Maşın öyrənməsi (ML) üsullarından istifadə olunmuşdur. Bu modellərin rüb ərzində üç fərqli dövr üzrə nümunədən kənar naukastinq qabiliyyətləri birdəyişənli bençmark modelinin naukastinq qabiliyyəti ilə müqayisə edilmişdir. Nəticələr göstərir ki, bençmark modeli ilə müqayisədə ML və DFM modelləri daha yüksək təxminetmə qabiliyyətinə malikdir və naukast xətalarını əhəmiyyətli dərəcədə azaldır. Ödəniş məlumatları üzrə zaman sırasının statistik cəhətdən etibarlı nəticələr əldə etmək üçün qısa olmasına baxmayaraq, nəticələr bu cür məlumatlarda yüksək tezlikli dəyişənlərin iqtisadiyyatın mövcud vəziyyətini qiymətləndirməkdə faydalı ola biləcəyini və iqtisadi aktivliyin real vaxt rejimində qiymətləndirilməsini təmin etmək potensialına malik olduğunu göstərir.$wp$, ARRAY[$wp$Ödəniş məlumatları$wp$, $wp$naukastinq$wp$, $wp$ML$wp$, $wp$DFM$wp$]::text[], $wp$6a4cf8e3c8c89c743b63f8a37.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Using National Payment System Data to Nowcast Economic Activity in Azerbaijan$wp$, ARRAY[$wp$Ilkin Huseynov$wp$, $wp$Nazrin Ramazanova$wp$, $wp$Hikmat Valirzayev$wp$]::text[], $wp$This study examines whether payment systems data can be useful in tracking economic activity in Azerbaijan. We utilize transactional payment systems data at the sectoral level and we employ Dynamic Factor Model (DFM) and Machine Learning (ML) techniques to nowcast quarter-over-quarter and year-over-year nominal GDP. We compare nowcasting performance of these models against the benchmark model in terms of out-of-sample RMSE at three different horizons during the quarter. The results suggest that payment system data along with ML and DFM models have higher predictability than benchmark model and can lower nowcast errors significantly. Although our payment time series are still too short to obtain statistically robust results, the findings indicate that variables at a higher frequency such payments systems data can be helpful to assess the current state of the economy and have the potential to provide a faster estimate of the economic activity.$wp$, ARRAY[$wp$payment data$wp$, $wp$nowcasting$wp$, $wp$ML$wp$, $wp$DFM$wp$]::text[], $wp$Using%20National%20Payment%20System%20Data%20to%20Nowcast%20Economic%20Activity%20in%20Azerbaijan_2022.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
