        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Bank kreditlərinin tələb və təklif amillərinin qiymətləndirilməsi$wp$, ARRAY[$wp$İlkin Hüseynov$wp$, $wp$Zübeydə İmanova$wp$, $wp$Hikmət Vəlirzayev$wp$]::text[], $wp$Məqalə Azərbaycanda Bank Kreditləşməsi Sorğusu (BLS) məlumatlarından istifadə etməklə bank kreditləşməsində tələb və təklif amillərinin rolunu araşdırır. Nəticələr göstərir ki, kredit artımında həm tələb, həm də təklif faktorları əhəmiyyətli rola sahibdir. İstehlak kreditlərinin rüblük artım tempinə kredit şərtlərinin yumşaldılmasının təsiri 0.14-0.21 faiz bəndi arasında, tələbin azalmasının təsiri isə -0.24 ilə -0.34 faiz bəndi arasında olmuşdur. Modelə müxtəlif kontrol dəyişənlər, zaman süni dəyişənləri və müxtəlif spesifikasiyalar tətbiq ediləndən sonra da qiymətləndirmənin nəticələri etibarlı olaraq qalır. Qiymətləndirmənin ikinci mərhələsində sistem əhəmiyyətli (SI) banklar və digərlərinin (NSI) nəticələri müqayisə edilmiş və təsirin müxtəlif bank qrupları üçün asimmetrik olduğu aşkar edilmişdir.$wp$, ARRAY[$wp$Bank Kreditləşməsi Sorğusu$wp$, $wp$panel data$wp$, $wp$kreditin artım tempi$wp$, $wp$tələb və təklif faktorları$wp$]::text[], $wp$500f99803d52ce337ff704921.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Disentangling the effect of supply and demand factors on bank lending. Evidence from Bank Lending Survey in Azerbaijan$wp$, ARRAY[$wp$Ilkin Huseynov$wp$, $wp$Zubeyda Imanova$wp$, $wp$Hikmat Valirzayev$wp$]::text[], $wp$This paper examines the role of supply and demand conditions in bank lending using data from the Bank Lending Survey (BLS) in Azerbaijan. Results suggest that both supply and demand factors play an important role in credit growth rate. The estimated impact of softening in credit conditions on the quarter-on-quarter consumer lending growth rate ranges between 0.14 and 0.21 percentage points while the effect of the decrease in demand is found to range between -0.24 and -0.34 percentage points, depending on the specifications. Results remain to be robust to the introduction of various control variables, time dummies, and different specifications. We further compare results for systematically important (SI) banks and others (NSI) and find that the effect is asymmetric for different bank groups.$wp$, ARRAY[$wp$Bank Lending Survey$wp$, $wp$panel data$wp$, $wp$credit growth$wp$, $wp$supply tightening$wp$]::text[], $wp$39f8b1739fbefafe9abd1e85d.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
