        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Azərbaycanın real effektiv məzənnəsinin tarazlıq səviyyəsinin davranış modeli əsasında qiymətləndirilməsi$wp$, ARRAY[$wp$Vüqar Rəhimov$wp$, $wp$Heyran Əliyeva$wp$]::text[], $wp$Bu məqalədə davranış modeli əsasında 2003R1-2018R1 dövrü üçün Azərbaycanın REM-ini formalaşdıran əsas determinantlar və faktiki REM-in modelin təklif etdiyi taraz REM səviyyəsindən kənarlaşması qiymətləndirilib. Tədqiqatın nəticələrinə görə, REM-in əvvəlki dövrdəki dəyəri (inersiyası), tərəfdaş ölkələrlə əmək məhsuldarlığı fərqi, real neft qiymətləri və xarici sektorla real faiz dərəcəsi fərqi REM-in əsas determinantlarıdır. Tədqiqatda həmçinin müxtəlif dövrlərdə taraz səviyyədən kənarlaşmaların olduğu məlum olur.$wp$, ARRAY[$wp$Real effektiv məzənnə$wp$, $wp$faktiki REM$wp$, $wp$davranış əsaslı REM modeli$wp$, $wp$kənarlaşma$wp$, $wp$Azərbaycan$wp$]::text[], $wp$c3d6b9cc6d900b43858321fba.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Estimation of Equilibrium Level of Real Effective Exchange Rate of Azerbaijan Using Behavioral Effective Exchange Rate Model$wp$, ARRAY[$wp$Vugar Rahimov$wp$, $wp$Heyran Aliyeva$wp$]::text[], $wp$In this paper, we examine the main variables affecting the REER of Azerbaijan using behavioral equilibrium exchange rate model and compute the degree of misalignment of actual REER from the equilibrium exchange rate suggested by the estimated model over 2003Q1-2018Q1. According to the results, own lag (inertia) of REER, labor productivity differentials with the main trading partners, real oil price and interest rate differentials with external sector are the main determinants of the REER. The study also reveals that there is misalignment from the equilibrium exchange rates at different time periods.$wp$, ARRAY[$wp$Real effective exchange rate$wp$, $wp$actual REER$wp$, $wp$behavioral equilibrium exchange rate model$wp$, $wp$misalignment$wp$, $wp$Azerbaijan$wp$]::text[], $wp$02_AZ%C6%8FRBAYCANIN%20REAL%20EFFEKT%C4%B0V%20M%C6%8FZ%C6%8FNN%C6%8FS%C4%B0N%C4%B0N%20TARAZLIQ%20S%C6%8FV%C4%B0YY%C6%8FS%C4%B0N%C4%B0N%20DAVRANI%C5%9E%20MODEL%C4%B0%20%C6%8FSASINDA%20Q%C4%B0YM%C6%8FTL%C6%8FND%C4%B0R%C4%B0LM%C6%8FS%C4%B0_2019.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
