        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Neft ixrac edən ölkələrdə pul və fiskal siyasətlərinin arasında qarşılıqlı əlaqə varmı? Azərbaycan təcrübəsi$wp$, ARRAY[$wp$Heyran Əliyeva$wp$, $wp$Ramiz Rəhmanov$wp$]::text[], $wp$Məqalədə VAR metodologiyası və 2003-2018-ci illəri əhatə edən rüblük statistik məlumatlar istifadə edilməklə Azərbaycanda fiskal və pul siyasətləri arasındakı qarşılıqlı əlaqə araşdırılmışdır. Qranger səbəbiyyət testləri və impuls reaksiya təhlilinin nəticələri göstərir ki, həm pul siyasəti, həm də fiskal siyasət aktivlik nümayiş etdirsə də, fiskal siyasət pul siyasətindən daha dominant mövqeyə malikdir. Fiskal rejim təsnifatı baxımından isə ölkədəki rejimi qeyri-Rikardian hesab etmək olar.$wp$, ARRAY[$wp$Fiskal siyasət$wp$, $wp$pul siyasəti$wp$, $wp$qarşılıqlı əlaqə$wp$, $wp$siyasət rejimləri$wp$, $wp$Azərbaycan$wp$]::text[], $wp$ac37592ae1075afb8e55ee850.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Do monetary and fiscal policies interact in oil-exporting countries? Evidence from Azerbaijan$wp$, ARRAY[$wp$Heyran Aliyeva$wp$, $wp$Ramiz Rahmanov$wp$]::text[], $wp$This paper examines the interaction between the fiscal and monetary policies in Azerbaijan using the VAR methodology and quarterly data for the period 2003Q1-2018Q4. The results of the Granger causality tests and impulse response analysis show that although both the monetary and fiscal policies demonstrate activity, the fiscal policy dominates over the monetary policy. In terms of the fiscal regime classification, we find the regime in the country to be non-Ricardian.$wp$, ARRAY[$wp$Fiscal policy$wp$, $wp$monetary policy$wp$, $wp$interaction$wp$, $wp$policy regimes$wp$, $wp$Azerbaijan$wp$]::text[], $wp$f940170296041791df0634f11.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
