        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Ölkə iqtisadiyyatı üzrə göstəricilərin modelləşdirilməsi və proqnozlaşdırılması məsələləri$wp$, ARRAY[$wp$M.Mehdiyev$wp$, $wp$V.Əhmədov$wp$, $wp$S.Hüseynov$wp$, $wp$F.Məmmədov$wp$]::text[], $wp$Cari məqalədə ölkə iqtisadiyyatı üzrə makroiqtisadi göstəricilərin modelləşdirilməsi və proqnozlaşdırılması zamanı qarşıya çıxan əsas çətinliklər tədqiq olunur. Bu məqsədlə qeyri-struktur modellər hesab olunan Vektor Avtoreqressiv (VAR) modellərdən istifadə edilir və müxtəlif göstəricilər arasında qarşılıqlı asılılıqlar qiymətləndirilir. Modelə daxil olan göstəricilərin ilkin müayinəsi və təhlili göstərir ki, onların dövrü dinamikasında volatillik mövcuddur. Təkcə bu faktorun özü göstəricilər arasında qarşılıqlı asılılıqları zəiflədən əsas amillərdən hesab oluna bilər. Heç də təəccüblü deyil ki, bir çox hallarda müxtəlif göstəricilərdən istifadə edərək ekonometrik modellər quran tədqiqatçılar onlar arasında statistik əhəmiyyətli asılılıqlar aşkar etməkdə çətinlik çəkirlər. Burada bir sıra statistik metodlardan istifadə etməklə həmin göstəricilərin dinamikasında mövcud olan volatillik və anomaliyaları azaltmağa çalışılır. Bu tədqiqat işində də tərkibinə müxtəlif sayda dəyişənlər daxil edilən VAR modelləri qiymətləndirilir və iki metodologiya (Vaqqoner və Zha (1999) və Banbura, Giannone və Lenza (2014)) əsasında müxtəlif göstəricilər üzrə şərtsiz və şərti proqnozlar hesablanır. Sonda modelləşdirmə və proqnozlaşdırama zamanı qarşıya çıxan praktiki çətinliklər göstərilir və statistik məlumatların keyfiyyətinin yaxşılaşdırılması üçün təkliflər verilir.$wp$, ARRAY[$wp$proqnozlaşdırma$wp$, $wp$zaman sırası metodları$wp$, $wp$Bayez metodları$wp$]::text[], $wp$692d8d05d91316b1c52d81d4e.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Modeling and forecasting of macroeconomic variables of the national economy: problems and practical issues$wp$, ARRAY[$wp$M.Mehdiyev$wp$, $wp$V.Ahmadov$wp$, $wp$S.Huseynov$wp$, $wp$F.Mammadov$wp$]::text[], $wp$In this paper, we study main problems and practical issues of modeling and forecasting of macroeconomic variables in the national economy. For that, we employ astructural VAR models and estimate interdependencies among different economic variables. Initial data analysis of macroeconomic variables incorporated into the model show that there exist certain anomalies and high volatility in their dynamics. Only that fact alone can be considered among important factors which strongly contribute to weak interdependencies among variables. It is not surprising that researchers using different macroeconomic variables on the national economy cannot find statistically significant relations among them. Here, we use different statistical methods to reduce volatilities and anomalies present in their dynamics. We estimate VAR models with different number of variables and employ two forecasting methodologies (Waggoner and Zha (1999), Banbura, Giannone and Lenza (2014)) to construct our conditional and unconditional forecasts on several variables. In the end, we demonstrate practical problems of modeling and forecasting of macroeconomic variables and provide some policy recommendations to improve quality of statistical data on the national economy.$wp$, ARRAY[$wp$Forecasting$wp$, $wp$time series methods$wp$, $wp$Bayes methods$wp$]::text[], $wp$08_%C3%96LK%C6%8F%20%C4%B0QT%C4%B0SAD%C4%B0YYATI%20%C3%9CZR%C6%8F%20G%C3%96ST%C6%8FR%C4%B0C%C4%B0L%C6%8FR.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
