        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İnflyasiya hədəflənməsinin əməliyyat çərçivəsi: ölkə təcrübələri AMB üçün nə vəd edir?$wp$, ARRAY[$wp$Ş.Adıgözəlov$wp$, $wp$S.Hüseynov$wp$]::text[], $wp$Hazırda inflyasiya hədəflənməsi (İH) rejimini elan edən aparıcı mərkəzi banklar buna adekvat əməliyyat çərçivəsini formalaşdırırlar. Lakin, pul siyasətinin transmissiyası ilə müqayisədə əməliyyat çərçivəsi akademik ədəbiyyatda və mərkəzi banklarda daha az tədqiq edilib. Cari məqalədə monetar siyasətin nisbətən “görünməyən üzü” olan əməliyyat çərçivəsi tədqiq edilir və bu məqsədlə, bir sıra aparıcı mərkəzi bankların təcrübəsi araşdırılır. Həmçinin, məqalədə Azərbaycan Mərkəzi Bankının (AMB) cari əməliyyat çərçivəsi də təhlil olunur və adekvat çərçivənin formalaşdırılması üçün təkliflər verilir.$wp$, ARRAY[$wp$İnflyasiya hədəflənməsi$wp$, $wp$əməliyyat çərçivəsi$wp$, $wp$transmissiya$wp$]::text[], $wp$d3fbb8c4833a53e542b94b05d.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Operational framework of inflation targeting: what promises do country experiences make to the CBAR?$wp$, ARRAY[$wp$S.Huseynov$wp$, $wp$Sh.Adigozalov$wp$]::text[], $wp$The CBAR plans to make a transition from the current peg regime where exchange rate acts as a “nominal anchor” to an inflation targeting (IT) regime. All leading central banks which adhere to an IT regime adopt a respective operational framework consistent with the announced monetary regime. Unfortunately, in compared to the transmission mechanism of the monetary policy which is under the spotlight, operational frameworks are not that much illuminated. This study explores a relatively “least conspicuous facet” of monetary policy, mainly focusing on experiences of various leading central banks. In addition, this paper analyzes the current operational framework of the Bank, pointing out the constraints and proposes several recommendations on how to adopt a proper operational framework for the new regime$wp$, ARRAY[$wp$Inflation targeting$wp$, $wp$operational framework$wp$, $wp$transmission$wp$]::text[], $wp$07_%C4%B0NFLYAS%C4%B0YA%20H%C6%8FD%C6%8FFL%C6%8FNM%C6%8FS%C4%B0N%C4%B0N%20%C6%8FM%C6%8FL%C4%B0YYAT%20%C3%87%C6%8FR%C3%87%C4%B0V%C6%8FS%C4%B0.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 06-2015, page-546
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 6 AND year = 2015) OR legacy_page_id = 546)) THEN
