        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İqtisadi artımla imkanlar bərabərsizliyi arasında əlaqə və onun istitusional aspektləri$wp$, ARRAY[$wp$G.Tahirova$wp$, $wp$R.Rəhmanov$wp$]::text[], $wp$Tədqiqat işində gəlir bərabərsizliyinin iqtisadi artıma təsir kanallarının konseptual sxemi qurulmuş və sabit effektlər, təsadüfi effektər, ümumiləşmiş momentlər üsulu vasitəsilə qiymətləndirmələr aparılmışdır. Qiymətləndirmələr inkişaf etmiş, inkişaf etməkdə olan və MDB ölkələri üzrə ayrılıqda yerinə yetirilmişdir. Qiymətləndirmələr inkişaf etmiş ölkələrdə fiskal, inkişaf etməkdə olan ölkələrdə kapital (investisiya) və insan kapitalı MDB ölkələrində isə kapital (investisiya) və fiskal kanalın vasitəsilə gəlir bərabərsizliyinin iqtisadi artıma təsir etdiyini göstərmişdir. Həmçinin gəlir bərabərsizliyi və iqtisadi artım arasında mənfi əlaqənin olduğu ekonometrik qiymətləndirmə ilə müəyyən edilmişdir.$wp$, ARRAY[$wp$gəlir bərabərsizliyi$wp$, $wp$iqtisadi artım$wp$, $wp$institusional mühit$wp$]::text[], $wp$30e3ea3053003581d02388c75.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$The relationship between economic growth and income inequality and its institutional aspects$wp$, ARRAY[$wp$G.Tahirova$wp$, $wp$R.Rahmanov$wp$]::text[], $wp$This paper aims to determine the channels through which income inequality affects economic growth using the fixed effects, random effects, and GMM techniques. The analysis covers developed, developing and CIS countries over the period 1980-2010. Our estimation results show that in the developing countries, the significant channel is government expenditure; in the developing countries, the significant channels are investment and human capital; in the CIS countries, the significant channels are government expenditure and investment. For all country groups, the relationship between income inequality and economic growth is negative.$wp$, ARRAY[$wp$income inequality$wp$, $wp$economic growth$wp$, $wp$institutions$wp$]::text[], $wp$04_%C4%B0QT%C4%B0SAD%C4%B0%20ARTIMLA%20%C4%B0MKANLAR%20B%C6%8FRAB%C6%8FRS%C4%B0ZL%C4%B0Y%C4%B0%20ARASINDA%20%C6%8FLAQ%C6%8F.pdf$wp$);
