        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Maliyyə vasitəçiliyi və iqtisadi artım$wp$, ARRAY[$wp$L.Yusifzadə$wp$, $wp$A.Məmmədova$wp$]::text[], $wp$Maliyyə dərinliyi maliyyə vasitəçilərinin iqtisadi artımı stimullaşdırmaqda iqtisadi agentlərə nə qədər yaxşı xidmət etdiyini tam əks etdirmir. Maliyyə və iqtisadi artım arasındakı əlaqənin ətraflı araşdırılması üçün maliyyə sisteminin əlçatanlıq (çıxış), səmərəlilik və sabitlik kimi digər göstəriciləri də nəzərə alınmalıdır. Məqaləmizdə maliyyə sektorunun inkişafının iqtisadi artıma təsirini araşdırmaq üçün dörd aspekti – maliyyə dərinliyi, maliyyələşməyə çıxış, səmərəlilik və maliyyə sabitliyini nəzərdən keçirmişik. Əldə etdiyimiz nəticələr göstərir ki, bu dörd parametrin təsiri maliyyə sektorunun inkişaf səviyyəsindən asılı olaraq dəyişir və tərs S-formalı funksiyaya malikdir.$wp$, ARRAY[$wp$Maliyyə vasitəçiləri$wp$, $wp$maliyyə inkişafı$wp$, $wp$iqtisadi artım$wp$, $wp$maliyyə dərinliyi$wp$, $wp$maliyyə əlçatanlığı$wp$, $wp$səmərəlilik$wp$, $wp$maliyyə sabitliyi$wp$]::text[], $wp$5e00d4a458fc6104fc273ed07.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Financial intermediation and economic growth$wp$, ARRAY[$wp$L.Yusifzada$wp$, $wp$A.Mammadova$wp$]::text[], $wp$Financial depth does not fully reflect how well the financial intermediaries serve to economic agents in stimulating economic growth. Additional aspects of financial system such as access, efficiency and stability should be taken into account in order to shed light into the relationship between finance and economic growth. In our paper we capture the four aspects of finance – depth, access, efficiency and stability – to investigate the impact of financial development and economic growth. Our results suggest that the impact of four parameters of financial development differs depending on the level of financial development and has an inverted S-shape function.$wp$, ARRAY[$wp$Financial intermediaries$wp$, $wp$financial development$wp$, $wp$economic growth$wp$, $wp$financial depth$wp$, $wp$access to finance$wp$, $wp$efficiency$wp$, $wp$financial stability$wp$]::text[], $wp$abea75ccb7e6c14891fae0a79.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
