        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Postkeçid dövründə ölkələrdə sərvət effekti: Azərbaycan nümunəsi$wp$, ARRAY[$wp$V.Əhmədov$wp$, $wp$R.Rəhmanov$wp$]::text[], $wp$Bu məqalədə sərvət effektinin Azərbaycan üzrə empirik analizi aparılmışdır. 2007-2013-cü illərin aylıq məlumatları əsasında Vektor təshihi modeli (VECM) metodologiyası tətbiq edilmişdir. Qiymətləndirmə nəticəsinə görə uzun müddətli dövrdə maliyyə sərvətinin elastikliyi 0.26 olmaqla statistik baxımdan əhəmiyyətli, daşınmaz əmlakın sərvət elastikliyi isə 0,05 olmaqla statistik baxımdan əhəmiyyətsizdir. Bundan əlavə, tədqiqat nəticələri göstərir ki, ev təsərrüfatlarının istehlaklarını uzunmüddətli tarazlıq səviyyəsinə uyğunlaşdırması üçün təxminən bir ay yarım vaxt lazımdır.$wp$, ARRAY[$wp$istehlak$wp$, $wp$daşınmaz əmlakın sərvət effekti$wp$, $wp$maliyyə sərvət effekti$wp$, $wp$postkeçid dövrü$wp$, $wp$Azərbaycan$wp$, $wp$Vektor təshihi modeli (VECM)$wp$]::text[], $wp$947f039380085a3dbdeeed428.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Wealth effects in post-transition countries : Evidence from Azerbaijan$wp$, ARRAY[$wp$V.Ahmadov$wp$, $wp$R.Rahmanov$wp$]::text[], $wp$This paper conducts an empirical analysis of the wealth effects in Azerbaijan. Applying the VECM methodology to the monthly data for the 2007-2013 period, we estimate that in the long run, the elasticity of financial wealth is 0.26 and statistically significant, whereas the elasticity of housing wealth is 0.05 but statistically insignificant. Furthermore, we find that it takes households about one month and a half to adjust their consumption to the long-run equilibrium level.$wp$, ARRAY[$wp$Consumption$wp$, $wp$housing wealth effect$wp$, $wp$financial wealth effect$wp$, $wp$post-transition$wp$, $wp$Azerbaijan$wp$, $wp$VECM$wp$]::text[], $wp$3e636ba5e23254a92296cee8b.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
