        VALUES (12, 2014, 'az', ARRAY[$wp$E42$wp$]::text[], 560, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Nağdsız ödənişlərin inkişaf səviyyəsinin iqtisadi artıma təsiri$wp$, ARRAY[$wp$L.Yusifzadə$wp$, $wp$A.Məmmədova$wp$]::text[], $wp$Tədqiqat işində nağdsız ödənişlərin inkişafını şərtləndirən dörd amil: institusional, infrastruktur, təklif və istifadə səviyyəsi, həmçinin yeniliklərin tətbiqinə meyillik üzrə indeks qurulub. Daha sonra ölkələr nağdsız ödənişlərin inkişafı baxımından qruplara bölünür. Nağdsız ödənişlərin inkişaf mərhələsindən asılı olaraq, hər bir ölkə qrupu üzrə hansı amillərin iqtisadi inkişafa təsir etdiyi müəyyən edilir.$wp$, ARRAY[$wp$Nağdsız ödənişlər$wp$, $wp$iqtisadi artım$wp$, $wp$institutsional inkişaf$wp$, $wp$infrastruktur$wp$]::text[], $wp$2ca87147d9b443ad148721561.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Impact of non-cash payments to economic growth$wp$, ARRAY[$wp$L.Yusifzada$wp$, $wp$A.Mammadova$wp$]::text[], $wp$Research paper builds an index based on four factors that are important for development of cashless economy: institutional environment, infrastructure, supply usage levels, and tendency to adopt innovations. Based on this index countries are classified into four different groups of cashless economy. Estimations identify the
most important factors that condition the contribution of the cashless payments to economic growth for each group of countries.$wp$, ARRAY[$wp$Cashless payment$wp$, $wp$economic growth$wp$, $wp$institutional development$wp$, $wp$infrastructure$wp$]::text[], $wp$12_NA%C4%9EDSIZ%20%C3%96D%C6%8FNI%C5%9EL%C6%8FRIN%20INKI%C5%9EAF%20S%C6%8FVIYY%C6%8FSI.pdf$wp$);
