        VALUES (11, 2014, 'az', ARRAY[$wp$G32$wp$]::text[], 559, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Kredit riskləri: Z-kəmiyyəti yanaşması$wp$, ARRAY[$wp$C.Abbasov$wp$]::text[], $wp$Tədqiqat işi Z-kəmiyyəti metodunun maliyyə sistemi üçün tətbiqinin nəzəri-praktiki məsələlərinə həsr olunub. Aydındır ki, bankdan borc götürmüş hər hansı müəssisənin maliyyə durumu nə qədər yaxşı olarsa, bir o qədər də kredit riskləri azalmış olar. Bu baxımdan borc götürmək istəyən hər hansı bir müəssisənin durumunun proqnozlaşdırılması istənilən bank üçün çox vacib bir məsələyə çevrilir. Bunun üçün iqisadi ədəbiyyatda müxtəlif yanaşmalar mövcuddur. Biz bu yanaşmalardan ən geniş isifadə olunan Altman və Edmisterin metodologiyalarını seçmişik. Məqalə məhz bu müəlliflərin baxışlarına həsr olunub.$wp$, ARRAY[$wp$kredit riski$wp$, $wp$Z-kəmiyyəti yanaşması$wp$, $wp$Kappa testi$wp$]::text[], $wp$84189b9caa3517c56507f9e9e.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Credit risks: The Z-Quantity approach$wp$, ARRAY[$wp$C.Abbasov$wp$]::text[], $wp$The research project was dedicated for the theoretical and practical issues of applying the Z-score methodology in the financial system. It is evident that, if the creditworthiness of a firm is higher, the default risk of a borrower will be lower. Therefore, predicting potential customer’s ability to serve its debt is crucial for the banks. For this reason, there are several approaches in the economic literature. We have chosen the mostly used methodology developed by Altman and Edminster. The article is discussing the views of these authors.$wp$, ARRAY[$wp$Credit risk$wp$, $wp$Z-score approach$wp$, $wp$Kappa test$wp$]::text[], $wp$11_KRED%C4%B0T%20R%C4%B0SKL%C6%8FR%C4%B0%20Z-K%C6%8FM%C4%B0YY%C6%8FT%C4%B0%20YANA%C5%9EMASI.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 10-2014, page-558
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 10 AND year = 2014) OR legacy_page_id = 558)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (10, 2014, 'az', ARRAY[$wp$F1$wp$, $wp$F4$wp$]::text[], 558, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İdxal və ixracın tələb və məzənnə elastikliyi$wp$, ARRAY[$wp$N.Əliyev$wp$, $wp$A.Qasımov$wp$, $wp$Ş.Adıgözəlov$wp$]::text[], $wp$Tədqiqat işində Azərbaycanın 2001-2012-ci illər üzrə idxal və ixracın tələb və məzənnə elastikliyi tədqiq edilmişdir. İdxal və ixrac göstəriciləri istehlak, aralıq və kapital məhsulları qruplarına bölünərək ayrı-ayrılıqda qiymətləndirilmişdir. Qiymətləndirmə üçün müqayisəli olaraq dəyişməyən effektlər (fixed effects), tam modifikasiya olunmuş ən kiçik kvadratlar (FMOLS) və ümumiləşdirilmiş momentlər metodu (GMM) kimi ekonometrik modellərindən istifadə olunmuşdur. Nəticələr göstərir ki, ölkənin ümumi və komponentlər üzrə ixracı xarici tələbə daha çox həssasdır və kəmiyyətcə çox yüksək müsbət elastikliyə malikdir. Kapital əmtəələrinin ixracının artımına xarici bazarlarda tələbin artması və məzənnənin möhkəmlənməsi tempi əhəmiyyətli təsir edir. İdxalda xüsusilə istehlak məhsullarının idxalı kəmiyyətcə daha yüksək müsbət məzənnə elastikliyi nümayiş etdirir.$wp$, ARRAY[$wp$idxal$wp$, $wp$ixrac$wp$, $wp$real ikitərəfli və effektiv məzənnə$wp$, $wp$daxili və xarici tələb$wp$]::text[], $wp$312722f439eae36cdbdaffd75.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Demand and exchange rate elasticity of import and export$wp$, ARRAY[$wp$N.Aliyev$wp$, $wp$A.Gasimov$wp$, $wp$Sh.Adigozalov$wp$]::text[], $wp$In this paper demand and exchange rate elasticity of import and export has been investigated over the 2001-2012 years in the case of Azerbaijan. Estimations has been done by decomposing import and export on consumption, intermediate and capital goods. Fixed effect model, FMOLS as well as GMM has been employed as a methodology of this paper. Results shows that, export (total as well as its components) has a higher positive foreign demand elasticity. Furthermore, growth of capital export mainly influenced by increase in foreign demand as well as by the exchange rate appreciation. Import of consumption goods also has a higher exchange rate elasticity.$wp$, ARRAY[$wp$Import$wp$, $wp$export$wp$, $wp$real bilateral and effective exchange rate$wp$, $wp$domestic and foreign demand$wp$]::text[], $wp$10_%C4%B0DXAL%20V%C6%8F%20%C4%B0XRACIN%20T%C6%8FL%C6%8FB%20V%C6%8F%20M%C6%8FZ%C6%8FNN%C6%8F%20ELAST%C4%B0KL%C4%B0Y%C4%B0.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
