    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 9 AND year = 2014) OR legacy_page_id = 557)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (9, 2014, 'az', ARRAY[$wp$F43$wp$, $wp$H72$wp$]::text[], 557, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Dövlət xərcləri və iqtisadi artım arasında əlaqələrin nəzəri-empirik tədqiq$wp$, ARRAY[$wp$G.Tahirova$wp$]::text[], $wp$Tədqiqat işi dövlət xərcləri və iqtisadi artım arasında əlaqənin araşdırılmasına həsr olunmuşdur. Bu məqsədlə müxtəlif ölkələr üzrə aparılmış tədqiqat işləri icmallaşdırılmış və BARS əyrisinin qiymətləndirilməsi üzrə nəticələr müqayisə edilmişdir.
Ümumilikdə, aparılmış tədqiqat işinin yekun nəticəsi büdcə xərcləri ilə ÜDM arasında mənfi əlaqənin olması fikrini təsdiqləməmişdir. Tədqiqatın nəticəsinə görə, büdcə xərclərinin effektivliyindən asılı olaraq, büdcə xərcləri və iqtisadi artım arasında əlaqə müsbət və ya mənfi ola bilər.$wp$, ARRAY[$wp$dövlət xərcləri$wp$, $wp$iqtisadi artım$wp$, $wp$BARS əyrisi$wp$]::text[], $wp$bcc1ef91949a4393b9679fac6.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Theoretical-empirical analysis of the relationship between government expenditure and economic growth$wp$, ARRAY[$wp$G.Tahirova$wp$]::text[], $wp$The article examines the relationship between government expenditure and economic growth. For this purpose, the existing literature is reviewed, and the estimation results of BARS curves are compared. In general, the conducted research does not confirm the existence of the negative relationship between government expenditure and economic growth. The results also show that whether the relationship between government expenditure and economic growth is negative or positive depends on the effectiveness of the government expenditure.$wp$, ARRAY[$wp$Government expenditure$wp$, $wp$economic growth$wp$, $wp$BARS curve$wp$]::text[], $wp$09_D%C3%96VL%C6%8FT%20X%C6%8FRCL%C6%8FRI%20V%C6%8F%20IQTISADI%20ARTIM.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
