        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Bank sistemində faiz riskinin ölçülməsi$wp$, ARRAY[$wp$A.Məmmədova$wp$, $wp$L.Yusifzadə$wp$]::text[], $wp$Tədqiqat işinin əsas məqsədi bank sistemi üzrə faiz riskinin ölçülməsidir. Tədqiqatda qəp təhlili, durasiya qəpi və Riskə Məruz Dəyər (RMD) kimi metodologiyalara baxılmışdır. İki hipotetik bank misalında faiz riski qiymətləndirilmiş və kapital adekvatlığı əmsalında nəzərə alınmışdır. Faiz riski nəzərə alındıqda belə, kapital adekvatlığı əmsalı şərti norma çərçivəsində olmuşdur.$wp$, ARRAY[$wp$faiz riski$wp$, $wp$qəp analizi$wp$, $wp$durasiya qəpi$wp$, $wp$Riskə Məruz Dəyər$wp$, $wp$risk- menecmentt$wp$]::text[], $wp$6188806ad6f9adef56143cd2f.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Measurement of interest rate risk in the banking system$wp$, ARRAY[$wp$A.Mammadova$wp$, $wp$L.Yusifzada$wp$]::text[], $wp$The main purpose of the research is to estimate interest rate risk for banking system. Paper reviews gap analysis, duration gap and Value at Risk (VAR) methodologies and measures interest rate risk for two hypothetical banks. Capital adequacy ratio, which is re-calculated based on interest rate risk measurement results, remains within the regulatory norm.$wp$, ARRAY[$wp$Interest rate risk$wp$, $wp$gap analysis$wp$, $wp$duration gap$wp$, $wp$Value at Risk$wp$, $wp$risk management$wp$]::text[], $wp$07_BANK%20S%C4%B0STEM%C4%B0ND%C6%8F%20FA%C4%B0Z%20R%C4%B0SK%C4%B0N%C4%B0N%20%C3%96L%C3%87%C3%9CLM%C6%8FS%C4%B0.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 06-2014, page-554
