    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 4 AND year = 2014) OR legacy_page_id = 552)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
