        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Məzənnə riskinin riskə məruz dəyər əsasında ölçülməsi$wp$, ARRAY[$wp$A.Zülfüqarov$wp$, $wp$L.Yusifzadə$wp$, $wp$A.Məmmədova$wp$]::text[], $wp$Tədqiqat işinin əsas məqsədi riskə məruz dəyərin (RMD) Azərbaycan bank sistemi üçün hesablanmasıdır. Tədqiqatda RMD-nin müxtəlif metodologiyaları (parametrik, tarixi simulyasiya və Monte-Karlo simulyasiyası) nəzərdən keçirilmişdir. İki hipotetik bank misalında məzənnə riski üzrə RMD hesablanmışdır. RMD-nin nəticələri məzənnə riskinin kiçik olduğunu göstərir. Məzənnə riski nəzərə alındıqda belə, kapital adekvatlığı əmsalı Azərbaycan Mərkəzi Bankı tərəfindən tələb edilən minimal həddən yüksəkdir.$wp$, ARRAY[$wp$Bazel$wp$, $wp$Riskə Məruz Dəyər$wp$, $wp$risk-menecment$wp$, $wp$xarici valyuta$wp$, $wp$məzənnə riski$wp$]::text[], $wp$b56e6ed791ff742ad03b9996d.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Estimation of exchange rate risk on the basis of the Value At Risk (VAR) model$wp$, ARRAY[$wp$A.Zulfugarov$wp$, $wp$L.Yusifzada$wp$, $wp$A.Mammadova$wp$]::text[], $wp$Main purpose of the research is to estimate Value at Risk (VAR) model for Azerbaijan banking sector. Different methodologies of VAR (parametric, historical simulation and Monte-Carlo simulation) were reviewed. VAR for currency risk was estimated for two hypothetical banks. VAR results for currency risk indicated that currency risk was lower. Even with the currency risk being taken into account, the capital adequacy ratio remains above the minimum capital requirement of the Central Bank.$wp$, ARRAY[$wp$Basel$wp$, $wp$VAR$wp$, $wp$risk management$wp$, $wp$foreign currency$wp$, $wp$exchange rate risk$wp$]::text[], $wp$03_M%C6%8FZ%C6%8FNN%C6%8F%20RISKININ%20RISK%C6%8F%20M%C6%8FRUZ%20D%C6%8FY%C6%8FR%20%C6%8FSASINDA%20%C3%96L%C3%87%C3%9CLM%C6%8FS%20I.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
