        VALUES (21, 2013, 'az', ARRAY[$wp$O15$wp$, $wp$P46$wp$]::text[], 584, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Yüksək gəlirli ölkəyə çevrilmək üçün Azərbaycanın üstünlükləri$wp$, ARRAY[$wp$Elman Eminov$wp$, $wp$Namiq Nağdəliyev$wp$]::text[], $wp$Məqalənin məqsədi sistemləşdirilmiş göstəricilər əsasında Azərbaycanın yuxarı orta gəlirli ölkələr arasındakı mövqeyinin müqayisəli təhlilini aparmaq və bununla da yüksək gəlirli ölkəyə çevrilmə imkanlarını müəyyən etməkdir.
Əsas gəlinən nəticə odur ki, Azərbaycanın qrup daxilində ən gənc ölkələrdən biri olmasına baxmayaraq, göstəricilərin bir çoxu üzrə digər ölkələrlə müqayisədə əhəmiyyətli üstünlüklərə malikdir. Növbəti gəlir qrupuna keçid üçün ölkənin əlverişli imkanları mövcuddur.$wp$, ARRAY[$wp$Gəlir qrupları$wp$, $wp$iqtisadi artımın sönməsi$wp$, $wp$orta gəlir tələsi$wp$, $wp$inkişaf fazaları$wp$]::text[], $wp$8f6ee9ce3025481a44c1a2bd5.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Azerbaijan`s advantages in transforming into high income country$wp$, ARRAY[$wp$E. Eminov$wp$, $wp$N. Nagdaliyev$wp$]::text[], $wp$The main purpose of the paper is to conduct analysis of Azerbaijan`s comparative ranking among upper middle-income countries on the basis of systemized indicators. Another purpose is to determine Azerbaijan`s advantages in transforming into high income country.
The essential finding is that Azerbaijan has significant advantages on many indicators in spite of the fact that the country is one of the youngest within upper middle income group. To move into the next income group the country has favorable opportunities.$wp$, ARRAY[$wp$Income groups$wp$, $wp$economic growth slowdown$wp$, $wp$middle income trap$wp$, $wp$development stages$wp$]::text[], $wp$22_Y%C3%BCks%C9%99k%20g%C9%99lirli%20%C3%B6lk%C9%99y%C9%99%20%C3%A7evrilm%C9%99k.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 20-2013, page-583
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 20 AND year = 2013) OR legacy_page_id = 583)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (20, 2013, 'az', ARRAY[$wp$E51$wp$, $wp$G21$wp$, $wp$E43$wp$]::text[], 583, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Nağdsız pul kütləsi ilə faiz dərəcələri arasında əlaqələr$wp$, ARRAY[$wp$Elçin Güləliyev$wp$, $wp$Xaqani Kərimov$wp$]::text[], $wp$“Bu tədqiqatda Azərbaycanda qeyri-nağd pul kütləsinin həcmi və kreditlər üzrə faiz dərəcələri arasında əlaqə araşdırılmış və faiz dərəcələrinin enməsi imkanları qiymətləndirilmişdir. Tədqiqatın başlıca nəticələrindən biri ondan ibarətdir ki, nağdsız pul dövriyyəsinin əhəmiyyətli genişlənməsi kreditlərin faiz dərəcələrinin aşağı enməsində ən başlıca amillərdən biridir.$wp$, ARRAY[$wp$Pul kütləsi$wp$, $wp$əmanət və depozitlər$wp$, $wp$kreditlər$wp$, $wp$faiz dərəcələri$wp$]::text[], $wp$9e03aec61d8a8395849b8c3f8.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$The relation between the cashless money supply and interest rates$wp$, ARRAY[$wp$E. Gulaliyev$wp$, $wp$Kh. Karimov$wp$]::text[], $wp$This paper analyzes the relation between the cashless money supply and interest rates for loans and assesses the room for a reduction of interest rates in Azerbaijan. The main finding of the research is that significant growth of the cashless money supply is a key factor to generate a decline in interest rates for loans in Azerbaijan.$wp$, ARRAY[$wp$Money supply$wp$, $wp$deposits and savings$wp$, $wp$credit$wp$, $wp$interest rate$wp$]::text[], $wp$21_Na%C4%9Fds%C4%B1z%20pul%20k%C3%BCtl%C9%99si%20il%C9%99%20faiz%20d%C9%99r%C9%99c%C9%99l%C9%99ri%20aras%C4%B1nda%20%C9%99laq%C9%99l%C9%99r.pdf$wp$);
