        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Məzənnə riskinin hesablanması: riskə məruz dəyər yanaşması$wp$, ARRAY[$wp$Tural Həsənov$wp$]::text[], $wp$Məzənnə riskinin hesablanması banklar üçün riskləri nəzarətdə saxlamaq və onları azaltmaq baxımından önəmlidir. Bankların balansında xaricdən cəlb olunan resurslarla yanaşı xarici valyutada olan aktivlər də yer alır. Bu səbəbdən məzənnədəki dəyişmədən asılı olaraq aktivlərin və ya öhdəliklərin bazar qiymətləri artıb-azala bilir. Məzənnədəki dəyişmənin təsiri bankların uzun və ya qısa valyuta mövqeyinə sahib olmalarından asılıdır. Bu tədqiqatda Azərbaycan bank sektorunda məzənnə riskini hesablamaq üçün Riskə Məruz Dəyər (RMD) modeli istifadə olunur. Modeldən çıxan nəticəyə əsasən ümumilikdə bank sistemi məzənnədəki dəyişmədən əhəmiyyətli təsirlənməyəcəklər.$wp$, ARRAY[$wp$məzənnə$wp$, $wp$risk-menecment$wp$, $wp$VAR$wp$, $wp$xarici valyuta$wp$, $wp$Azərbaycan bank sistemi$wp$, $wp$Riskə Məruz Dəyər$wp$]::text[], $wp$dc18afb76beacd95890c0ddf9.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Exchange rate risk measurement: Value at Risk approach$wp$, ARRAY[$wp$T. Hasanov$wp$]::text[], $wp$Exchange rate risk measurement is essential for the banking system as it helps monitor and reduce the vulnerabilities that banks are exposed to. Banks finance part of their business activities with the external funding and also have assets in foreign currencies values of which can deteriorate or improve depending on the movement of the exchange rates and the foreign currency borrowing concentration of the bank. In this paper VAR (Value at Risk) method was used to calculate the exchange rate risk in the Azerbaijan banking sector. Model reveals that banking system won`t be substantially affected from the variations in exchange rate.$wp$, ARRAY[$wp$Exchange rate$wp$, $wp$risk management$wp$, $wp$VAR$wp$, $wp$foreign currency$wp$, $wp$Azerbaijan banking sector$wp$, $wp$Value-at-Risk$wp$]::text[], $wp$20_M%C9%99z%C9%99nn%C9%99%20riskinin%20hesablanmas%C4%B1.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
