    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 16 AND year = 2013) OR legacy_page_id = 579)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (16, 2013, 'az', ARRAY[$wp$O24$wp$]::text[], 579, 'published')
