        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İnkişaf edən ölkələrdə məzənnə rejimləri və Azərbaycan təcrübəsi$wp$, ARRAY[$wp$Əlirzayeva Təranə$wp$]::text[], $wp$Uzun illərdir ölkələr üçün uyğun məzənnə rejiminin seçilməsi məsələsi geniş müzakirə mövzusudur. Müxtəlif məzənnə rejimlərinin müsbət və mənfi tərəfləri, uyğun rejimin seçilməsində determinantların müəyyənləşdirilməsi kimi mürəkkəb sualların cavablandırılması dərin tədqiqatlar tələb edir. Təbii resurslarla zəngin ölkələrdə məzənnə rejimlərinin seçimi ölkə spesifikalarını da nəzərə almaqla xüsusi yanaşma tələb edir. Bu tədqiqatın məqsədi ölkələrdə məzənnə rejimlərinin seçim meyarlarını müəyyənləşdirmək, o cümlədən Azərbaycanın bu sahədə təcrübəsini qiymətləndirməkdən ibarətdir.$wp$, ARRAY[$wp$məzənnə rejimləri$wp$, $wp$təsbit məzənnə$wp$, $wp$valyuta müdaxiləsi$wp$]::text[], $wp$42dbe21bdeb748c0a731e79e4.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Exchange rate regimes in developing countries and Azerbaijan experience$wp$, ARRAY[$wp$T. Alirzayeva$wp$]::text[], $wp$There are constant debates on the choice of the relevant exchange rate regime for countries. Evaluation of the positive and negative impacts of different exchange rate regimes and search for proper determinants require extensive research. Moreover special approaches are needed for the resource rich countries. The main purpose of this research is to find out the proper selection criteria of the exchange rate regime in different countries and evaluate the experience of Azerbaijan as well.$wp$, ARRAY[$wp$Exchange rate regime$wp$, $wp$fixed exchange rate$wp$, $wp$intervention$wp$]::text[], $wp$17_%C4%B0nki%C5%9Faf%20ed%C9%99n%20%C3%B6lk%C9%99l%C9%99rd%C9%99%20m%C9%99z%C9%99nn%C9%99%20rejiml%C9%99ri.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
