        VALUES (15, 2013, 'az', ARRAY[$wp$E30$wp$, $wp$E31$wp$]::text[], 578, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İnflyasiya hədəfi: baza yoxsa məcmu inflyasiya?$wp$, ARRAY[$wp$Ramiz Rəhmanov$wp$, $wp$Salman Hüseynov$wp$, $wp$Şaiq Adıgözəlov$wp$]::text[], $wp$Qarşısına inflyasiyanın hədəflənməsi rejiminə keçid məqsədi qoyan mərkəzi banklar həm də müvafiq qiymət indeksinin seçilməsi ilə bağlı qərar verməlidirlər. Bu qərar verilərkən bir sıra meyarlar nəzərə alınır, mövcud qiymət indeksləri arasında "fayda-itki" təhlilləri aparılır, hər birinin müqayisəli üstünlükləri aşkara çıxarılır. Bu məqalədə orta müddətli dövrdə Azərbaycan Mərkəzi Bankının (AMB) müvafiq qiymət indeksinin, məcmu yoxsa baza göstəricisini hədəf olaraq götürməsi məsələsi tədqiq edilir. Mövcud baza inflyasiya ilə yanaşı Bayez Dinamik Faktor modelindən istifadə etməklə yeni baza inflyasiya göstəricisi hesablanır, müxtəlif statistik testlər əsasında göstəricilərin adekvatlığı yoxlanılır. Qiymətləndirmələr göstərir ki, yeni baza inflyasiya göstəricisi inflyasiyanın uzun müddətli trend göstəricisi kimi qəbul oluna bilər, mövcud göstərici isə qısa müddətli dövrdə tələb olunan statistik meyarları ödəyir. Nəticə olaraq qeyd olunur ki, qərarvermə prosesində AMB, trend göstəricisi kimi yeni baza inflyasiya göstəricisini əhəmiyyətli məlumat yükünə malik indikator kimi nəzərə ala bilər. Bununla belə, verilən pul siyasəti qərarlarının ictimaiyyət tərəfindən rahat anlaşılması üçün məcmu inflyasiya göstəricisinin hədəf kimi götürülməsi məqsədəuyğun olardı.$wp$, ARRAY[$wp$istehlak qiymət indeksi$wp$, $wp$baza inflyasiya$wp$, $wp$Gibz alqoritmi$wp$]::text[], $wp$7464c921289f9e909eb08d248.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Inflation targeting: core or headline inflation?$wp$, ARRAY[$wp$R. Rahmanov$wp$, $wp$S. Huseynov$wp$, $wp$Sh Adigozalov$wp$]::text[], $wp$The central banks which aim to shift to inflation targeting framework have to make a decision regarding the price index they will target. However, before making the final decision, several criteria must be taken into consideration, “cost-benefit” analysis of existing price indices must be made and comparative advantages of each index must be revealed.
The article discusses whether the Central Bank of the Republic of Azerbaijan plans to the medium run should target headline inflation or core inflation. Along with existing core inflation, using the Bayesian Dynamic Factor model, the new core inflation is calculated and furthermore, several statistical tests are applied to test adequacy of the new core inflation measure.
The estimations show that the new core inflation can be used as an indicator of the long run trend of inflation, whereas the existing core inflation is a good indicator in the short run. The article concludes that in a decision making process, the Central Bank should use the new core inflation measure as a trend indicator since it contains much more information than the existing one. However, to make monetary policy decisions comprehensible to the public, it is recommended to target headline inflation.$wp$, ARRAY[$wp$Consumer price index$wp$, $wp$core inflation$wp$, $wp$Gibbs algorithm$wp$]::text[], $wp$16_%C4%B0nflyasiya%20h%C9%99d%C9%99fi.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
