        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (13, 2013, 'az', ARRAY[$wp$G21$wp$, $wp$G28$wp$]::text[], 576, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Bank sistemində maliyyə vasitəçiliyi göstəricilərinin maliyyə dərinliyinə təsiri$wp$, ARRAY[$wp$Rəşad Kərimov$wp$]::text[], $wp$Məqalədə Azərbaycanda bank sektorunun maliyyə vasitəçiliyi göstəriciləri və onların maliyyə dərinliyinə təsiri qiymətləndirilmişdir. Azərbaycanda bank kreditləri ümumi kreditlərin 97.5 faizini, qeyri-bank kreditləri isə cəmi 2.5 faizini təşkil edir. Eyni zamanda, xarici kapitallı bankların təklif etdiyi kreditlərin ümumi kreditlərdə payı 33 faiz, yerli banklarda isə bu göstərici 67 faizdir.
Araşdırmalar göstərir ki, qeyri-bank kreditlərinin 10% artımı maliyyə dərinliyinə 0.78%, bank kreditlərinin 10% artımı isə maliyyə dərinliyinə 1.25% müsbət təsir göstərir.$wp$, ARRAY[$wp$maliyyə vasitəçiliyi$wp$, $wp$maliyyə dərinliyi$wp$, $wp$bank kreditləri$wp$]::text[], $wp$c31b8ca0e47c2249a2fd75fa4.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$The impact of financial intermediation indicators on financial depth in the banking system$wp$, ARRAY[$wp$R. Karimov$wp$]::text[], $wp$This article investigates the indicators of financial intermediation, as well as their effect on financial depth. The study analyzes financial intermediary indicators of the banking sector in Azerbaijan and determines the effect of those indicators on financial depth by carrying out an econometric evaluation based on OLS model.
Bank credits in Azerbaijan are found to be 97.5% of the overall credits, whereas the other part is included in non-bank credits. This research considers issues regarding the banks with both foreign and local capital and it shows that loans given by the banks with the foreign capital include 33% of the all available loans and the left 77% belong to the banks with the local capital.
Results let us see that 10% increase in bank credits induce financial depth to amplify by 1.25%, while 10% increase in non-bank credits make financial depth to rise by 0.78%.$wp$, ARRAY[$wp$Financial intermediation$wp$, $wp$financial depth$wp$, $wp$bank credits$wp$]::text[], $wp$14_Bank%20sistemind%C9%99%20maliyy%C9%99%20vasit%C9%99%C3%A7iliyi.pdf$wp$);
        created := created + 1;
