        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Valyuta ehtiyatlarının idarə olunması: yeni yanaşmalar$wp$, ARRAY[$wp$Aftandil Babayev$wp$]::text[], $wp$Asiya böhranından sonra dünyada valyuta ehtiyatlarının əhəmiyyətli artması ehtiyatların idarə edilməsinə və onun maliyyə bazarlarına təsirinə diqqəti artırmışdır. Son 10 ildə isə dünyada ehtiyatların idarə edilməsi təcrübəsi əhəmiyyətli dərəcədə inkişaf etmiş, bu inkişaf həm də iqtisadi və institusional mühitdə baş verən dəyişiklikləri özündə əks etdirmişdir.
Məqalədə də ehtiyatların idarə olunmasına dair beynəlxalq təcrübə təhlil edilmiş, bu dəyişikliyin əsas səbəbləri göstərilmiş və post-böhran dövrünün çağırışları ümumiləşdirilmişdir. Xüsusilə maliyyə bazarlarına təsir edə biləcək çağırışlara önəm verilmişdir.$wp$, ARRAY[$wp$mərkəzi bankçılıq$wp$, $wp$maliyyə böhranı$wp$, $wp$maliyyə sabitliyi$wp$, $wp$rezervlərin idarə edilməsi$wp$]::text[], $wp$50f120da140cf7ef6ca06ea34.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$The management of foreign exchange reserves: new approaches$wp$, ARRAY[$wp$A. Babayev$wp$]::text[], $wp$The increasing size of official foreign exchange reserves after years of continued expansion, especially since the Asian crisis, have led to rising interest for the ways of asset management and the impact of reserves on financial markets. Reserve management practices have evolved substantially over the past decade or so, reflecting changes in both the economic and the broader institutional environment.
This paper documents some of the main changes in foreign exchange reserve management practices, considers the main drivers behind them, and explores some of the challenges ahead. Special focus is given on those challenges that could have a more significant impact on financial markets.$wp$, ARRAY[$wp$Central bank$wp$, $wp$financial crisis$wp$, $wp$financial stability$wp$, $wp$reserve management$wp$]::text[], $wp$12_Valyuta%20ehtiyatlar%C4%B1n%C4%B1n.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
