        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Oyun nəzəriyyəsi: monetar və fiskal siyasətlərin davranış modelləri$wp$, ARRAY[$wp$Xaqani Abdullayev$wp$]::text[], $wp$İnkişaf etmiş və inkişaf etməkdə olan ölkələrdə monetar və fiskal qurumların davranışları və makroiqtisadi siyasət çərçivəsində koordinasiya meyilləri bir-birindən fərqlənir. Bu səbəbdən tədqiqat işində iqtisadi artım və inflyasiyanın hədəflənməsi baxımından oyun nəzəriyyəsi çərçivəsində fiskal və monetar qurumların davranışları tədqiq edilmişdir. Beş müxtəlif oyun nəzriyyəsinə əsaslanan təhlillər göstərir ki, hər iki qurumun koordinasiya şəraitində əldə etdiyi faydalar koordinasiya olmadan əldə olunan faydalardan böyükdur.$wp$, ARRAY[$wp$oyun nəzəriyyəsi$wp$, $wp$fiskal kəsir$wp$, $wp$inflyasiya hədəflənməsi$wp$, $wp$Nəş tarazlığı$wp$]::text[], $wp$046275f5c49de58063513bc74.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Game theory: behavioral models of monetary and fiscal policies$wp$, ARRAY[$wp$Kh. Abdullayev$wp$]::text[], $wp$Behaviors of fiscal and monetary bodies in developing countries highly differ from those of developed economies. Therefore, the current paper investigates behaviors of fiscal and monetary bodies targeting inflation and economic growth using the game theoretic approach. Results from five different games demonstrate that the benefits for both bodies from cooperative games are higher than those of non-cooperative games.$wp$, ARRAY[$wp$Game theory$wp$, $wp$fiscal deficit$wp$, $wp$inflation targeting$wp$, $wp$Nash equilibrium$wp$]::text[], $wp$09_Oyun%20n%C9%99z%C9%99riyy%C9%99si%20monetar%20v%C9%99%20fiskal.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
    -- 07-2013, page-570
    IF NOT EXISTS (SELECT FROM working_papers WHERE deleted_at IS NULL AND ((number = 7 AND year = 2013) OR legacy_page_id = 570)) THEN
        INSERT INTO working_papers (number, year, paper_language, jel_codes, legacy_page_id, status)
        VALUES (7, 2013, 'az', ARRAY[$wp$O24$wp$]::text[], 570, 'published')
        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Mübadilə məzənnəsinin real sektorun sahələrinə təsiri$wp$, ARRAY[$wp$Asif Qasımov$wp$, $wp$Xəqani Kərimov$wp$]::text[], $wp$Tədqiqat işində manatın məzənnəsinin real sektorun ayrı-ayrı sahələrinə təsiri tədqiq edilmişdir. Bu təsirin müxtəlif sahəvi effektivliyə malik olmasını nəzərə alaraq, real sektorun sahələrinin funksional təsnifat metodologiyası işlənmişdir. Hər bir sahənin cari rəqabət qabiliyyətinin mövcud vəziyyətini qiymətləndirmək üçün sahəvi real effektiv məzənnə hesablanmışdır. Sahələrin rəqabət qabiliyyətinin determinantlarını müəyyən etmək üçün 2002-2009-cu illəri və 15 tərəfdaş ölkənin müvafiq məlumatlarını əhatə edən panel reqressiyası qiymətləndirməsi tətbiq olunmuşdur.$wp$, ARRAY[$wp$rəqabət qabiliyyəti$wp$, $wp$məzənnənin ötürücülüyü$wp$]::text[], $wp$93a5a9cbbbefb25fe00258f73.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$The impact of the exchange rate on the real sector$wp$, ARRAY[$wp$A. Gasimov$wp$, $wp$Kh. Karimov$wp$]::text[], $wp$Recent paper investigates the effects of the exchange rate on subsectors of the real economy. Taking into account the various effects of exchange rate on different subsectors of real economy the latter has been functionally classified. To estimate the current competitiveness of each subsector, sectoral real effective exchange rates have been calculated. To find out determinants of the sectoral competitiveness panel regression has been used covering data of 15 partner countries and the period of 2002-2009.$wp$, ARRAY[$wp$Competitiveness$wp$, $wp$exchange rate pass-through$wp$]::text[], $wp$08_M%C3%BCbadil%C9%99%20m%C9%99z%C9%99nn%C9%99si.pdf$wp$);
        created := created + 1;
    ELSE
        skipped := skipped + 1;
    END IF;
