        RETURNING id INTO pid;
        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Manatın məzənnəsinin inflyasiyaya ötürücülük qabiliyyəti$wp$, ARRAY[$wp$Xəqani Kərimov$wp$]::text[], $wp$Məqalədə məzənnədə dəyişmənin qiymətlərə ötürücülüyü kəmiyyətcə qiymətləndirilmiş və Azərbaycan şəraitində müvafiq xüsusiyyətlər təhlil edilmişdir. Bununla belə müxtəlif ekonometrik alətlərdən istifadə etməklə nominal effektiv məzənnədə baş verən dəyişikliklər nəticəsində istehlak qiymətlərinin necə təsirləndiyi müəyyən edilmişdir.$wp$, ARRAY[$wp$məzənnə$wp$, $wp$nominal effektiv məzənnə$wp$, $wp$məzənnə ötürücülüyü$wp$, $wp$inflyasiya$wp$]::text[], $wp$5cb8883a6512b263e29eb9643.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Exchange rate pass-through to inflation in Azerbaijan$wp$, ARRAY[$wp$Kh. Karimov$wp$]::text[], $wp$The article presents the results of quantitative estimation of level with analysis of relevant specifications in the case of Azerbaijan. Furthermore, the impact of changes in nominal effective exchange rate to consumer prices was determined using econometric tools.$wp$, ARRAY[$wp$Exchange rate$wp$, $wp$nominal effective exchange rate$wp$, $wp$exchange rate passthrough$wp$, $wp$inflation$wp$]::text[], $wp$07_%C4%B0nflyasiyaya%20%C3%B6t%C3%BCr%C3%BCc%C3%BCl%C3%BCk.pdf$wp$);
