        PERFORM pg_temp.wp_translation(pid, 'az', $wp$İnflyasiyanın optimal həddinin qiymətləndirilməsi$wp$, ARRAY[$wp$Şaiq Adıgözəlov$wp$, $wp$Vüqar Əhmədov$wp$]::text[], $wp$Məqalədə inflyasiyanın iqtisadi artım üçün zərərli olmayan həddi qiymətləndirilmişdir. Qiymətləndirmə kritik həddin müəyyən edilməsinə dair reqressiya modelinə əsaslanır. Aparılmış qiymətləndirmə Azərbaycanda inflyasiya ilə iqtisadi artım arasında qeyri-xətti əlaqənin olmasını göstərir.$wp$, ARRAY[$wp$inflyasiya$wp$, $wp$iqtisadi artım$wp$, $wp$kritik hədd$wp$, $wp$ticarət şəraiti indeksi$wp$]::text[], $wp$ab280f3f4c5c135ad5a50e7dd.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Estimation of optimal inflation rate$wp$, ARRAY[$wp$Sh. Adigozalov$wp$, $wp$V. Ahmadov$wp$]::text[], $wp$The study estimates the threshold level of inflation affecting the economic growth in Azerbaijan using OLS framework. The study revealed the non-linear relationship between inflation and economic growth in the country.$wp$, ARRAY[$wp$inflation$wp$, $wp$economic growth$wp$, $wp$critical threshold$wp$, $wp$trade conditions index$wp$]::text[], $wp$03_%C4%B0nflyasiyan%C4%B1n%20optimal%20h%C9%99ddi.pdf$wp$);
