        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Daşınmaz əmlak bazarında qiymət səviyyəsinin qiymətləndirilməsi$wp$, ARRAY[$wp$Şaiq Adıgözəlov$wp$, $wp$Xəqani Kərimov$wp$, $wp$Heyran Əliyeva$wp$]::text[], $wp$Məqalədə fundamental iqtisadi amillərin analizi əsasında Azərbaycanda daşınmaz əmlak bazarında qiymətlərin tarazlı səviyyəsi müəyyənləşdirilmişdir. Alınmış nəticə daşınmaz əmlakın faktiki qiymət səviyyəsi ilə müqayisə edilmiş və “köpük”lərin mövcud səviyyəsi dəyərləndirilmişdir.$wp$, ARRAY[$wp$daşınmaz əmlak$wp$, $wp$köpük$wp$, $wp$əmlaka tələb və təklif$wp$, $wp$ilkin və təkrar əmlak bazarı$wp$]::text[], $wp$7b9ac1523b66f1550526e8686.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Estimation of the price level in the real estate market$wp$, ARRAY[$wp$Sh. Adigozalov$wp$, $wp$Kh. Karimov$wp$, $wp$H. Aliyeva$wp$]::text[], $wp$In the article the equilibrium price level in the real estate market was estimated on the basis of economic fundamentals. Results were compared with the actual price level in the real estate market to estimate the size of the “bubble”.$wp$, ARRAY[$wp$Real estate market$wp$, $wp$bubble$wp$, $wp$property demand and supply$wp$, $wp$primary and secondary real estate market$wp$]::text[], $wp$02_Da%C5%9F%C4%B1nmaz%20%C9%99mlak%20bazar%C4%B1nda%20qiym%C9%99t.pdf$wp$);
