        PERFORM pg_temp.wp_translation(pid, 'az', $wp$Bank böhranları: qiymətləndirmə metododologiyaları$wp$, ARRAY[$wp$Asim Zülfüqarov$wp$, $wp$Orxan İsmayılov$wp$]::text[], $wp$Tәdqiqat işinin әsas mәqsәdi bank böhranlarının әvvәlcәdәn müәyyәn edilmәsi vә qiymәtlәndirilmәsi mәqsәdi ilә istifadә edilәn indekslәrin nәzәri vә tәcrübi aspektlәrinin araşdırılmasından ibarәtdir. Tәdqiqat işindә beynәlxalq tәcrübәdә geniş istifadә edilәn dörd indeks nәzәrdәn keçirilmiş, Azәrbaycan bank sistemi iki indeks vasitәsilә qiymәtlәndirilmişdir. İndekslәr hәm standartlaşdırma, hәm dә klassik çәki metodları ilә hesablanmışdır. Әldә edilmiş nәticәlәr Azәrbaycan bank sisteminin stabil inkişaf mәrhәlәsindә olduğunu göstәrir.$wp$, ARRAY[$wp$böhran$wp$, $wp$maliyyә sabitliyi$wp$, $wp$maliyyә dayanıqlılığı$wp$]::text[], $wp$b0347dfad0d25b4eb8fd6b81d.pdf$wp$);
        PERFORM pg_temp.wp_translation(pid, 'en', $wp$Banking crises: assessment methodologies$wp$, ARRAY[$wp$A. Zulfugarov$wp$, $wp$O. Ismayilov$wp$]::text[], $wp$The main purpose of this paper is to analyze theoretical and practical aspects of different indexes used as banking crisis indicators. Four indexes widely used in international experience have been reviewed in this research paper. Two of these indexes have been implemented for the purpose of risk estimation in Azerbaijan banking system. Indexes have been valued by standardization and classical weight methods. Findings show that Azerbaijan banking system is in the stage of stable development.$wp$, ARRAY[$wp$Crisis$wp$, $wp$financial stability$wp$, $wp$financial sustainability$wp$]::text[], $wp$01_Bank%20b%C3%B6hranlar%C4%B1%20qiym%C9%99tl%C9%99ndirm%C9%99.pdf$wp$);
